'use client';

import React from 'react';
import Sidebar from './Sidebar';

interface DashboardLayoutProps {
    children: React.ReactNode;
    activeView: 'home' | 'datasets' | 'upload' | 'reports';
    onViewChange: (view: 'home' | 'datasets' | 'upload' | 'reports') => void;
    onLogout: () => void;
    userName?: string;
}

export default function DashboardLayout({
    children,
    activeView,
    onViewChange,
    onLogout,
    userName
}: DashboardLayoutProps) {
    return (
        <div className="dashboard-layout">
            <Sidebar
                activeView={activeView}
                onViewChange={onViewChange}
                onLogout={onLogout}
                userName={userName}
            />
            <main className="dashboard-content">
                {children}
            </main>

            <style jsx>{`
                .dashboard-layout {
                    display: flex;
                    min-height: 100vh;
                    background: var(--background);
                }

                .dashboard-content {
                    flex: 1;
                    height: 100vh;
                    overflow-y: auto;
                    position: relative;
                }
            `}</style>
        </div>
    );
}
