'use client';

import React from 'react';
import { Home, Database, Upload, LogOut, Activity as SphereIcon, ChevronLeft, ChevronRight } from 'lucide-react';

interface SidebarProps {
    activeView: 'home' | 'datasets' | 'upload' | 'reports';
    onViewChange: (view: 'home' | 'datasets' | 'upload' | 'reports') => void;
    onLogout: () => void;
    userName?: string;
}

export default function Sidebar({ activeView, onViewChange, onLogout, userName }: SidebarProps) {
    const [isCollapsed, setIsCollapsed] = React.useState(false);

    const menuItems = [
        { id: 'home', label: 'Inicio', icon: <Home size={20} /> },
        { id: 'datasets', label: 'Mis datasets', icon: <Database size={20} /> },
        { id: 'reports', label: 'Mis reportes', icon: <SphereIcon size={20} /> },
        { id: 'upload', label: 'Subir dataset', icon: <Upload size={20} /> },
    ];

    const toggleCollapse = () => setIsCollapsed(!isCollapsed);

    return (
        <aside className={`sidebar ${isCollapsed ? 'collapsed' : ''}`}>
            <div className="sidebar-header">
                <div className="logo-container">
                    <div className="logo-orb"></div>
                    {!isCollapsed && <span className="logo-text">Sphere</span>}
                </div>
                <button className="collapse-toggle" onClick={toggleCollapse}>
                    {isCollapsed ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}
                </button>
            </div>

            <nav className="sidebar-nav">
                {menuItems.map((item) => (
                    <button
                        key={item.id}
                        className={`nav-item ${activeView === item.id ? 'active' : ''}`}
                        onClick={() => onViewChange(item.id as any)}
                        title={isCollapsed ? item.label : undefined}
                    >
                        {item.icon}
                        {!isCollapsed && <span>{item.label}</span>}
                    </button>
                ))}
            </nav>

            <div className="sidebar-footer">
                {userName && (
                    <div className="user-info">
                        <div className="user-avatar">
                            {userName.charAt(0).toUpperCase()}
                        </div>
                        {!isCollapsed && (
                            <div className="user-details">
                                <span className="user-name">{userName}</span>
                            </div>
                        )}
                    </div>
                )}
                <button
                    className="nav-item logout-btn"
                    onClick={onLogout}
                    title={isCollapsed ? "Salir" : undefined}
                >
                    <LogOut size={20} />
                    {!isCollapsed && <span>Salir</span>}
                </button>
            </div>

            <style jsx>{`
                .sidebar {
                    width: 260px;
                    height: 100vh;
                    background: var(--surface);
                    border-right: 1px solid var(--border);
                    display: flex;
                    flex-direction: column;
                    position: sticky;
                    top: 0;
                    z-index: 100;
                    transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
                }

                .sidebar.collapsed {
                    width: 80px;
                }

                .sidebar-header {
                    padding: 32px 24px;
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    position: relative;
                }

                .sidebar.collapsed .sidebar-header {
                    padding: 32px 0;
                    justify-content: center;
                }

                .logo-container {
                    display: flex;
                    align-items: center;
                    gap: 12px;
                }

                .logo-orb {
                    width: 32px;
                    height: 32px;
                    background: linear-gradient(135deg, var(--primary), var(--secondary));
                    border-radius: 50%;
                    box-shadow: 0 0 15px var(--primary-glow);
                    position: relative;
                }

                .logo-orb::after {
                    content: '';
                    position: absolute;
                    top: 4px;
                    left: 4px;
                    width: 8px;
                    height: 8px;
                    background: rgba(255, 255, 255, 0.4);
                    border-radius: 50%;
                }

                .logo-text {
                    font-size: 1.5rem;
                    font-weight: 700;
                    letter-spacing: -0.5px;
                    background: linear-gradient(to right, #fff, #a1a1aa);
                    -webkit-background-clip: text;
                    -webkit-text-fill-color: transparent;
                }

                .collapse-toggle {
                    background: var(--surface-light);
                    border: 1px solid var(--border);
                    border-radius: 6px;
                    width: 24px;
                    height: 24px;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    cursor: pointer;
                    color: var(--text-muted);
                    transition: all 0.2s;
                    position: absolute;
                    right: -12px;
                    top: 40px;
                    z-index: 10;
                }

                .sidebar.collapsed .collapse-toggle {
                    right: auto;
                    top: 24px;
                    position: absolute;
                    transform: translateX(35px);
                }

                .collapse-toggle:hover {
                    color: var(--primary);
                    border-color: var(--primary);
                    background: var(--background);
                }

                .sidebar-nav {
                    flex: 1;
                    padding: 0 16px;
                    display: flex;
                    flex-direction: column;
                    gap: 4px;
                }

                .nav-item {
                    display: flex;
                    align-items: center;
                    gap: 12px;
                    padding: 12px 16px;
                    background: transparent;
                    border: none;
                    border-radius: 12px;
                    color: var(--text-muted);
                    font-size: 0.9375rem;
                    font-weight: 500;
                    cursor: pointer;
                    transition: all 0.2s ease;
                    text-align: left;
                    white-space: nowrap;
                    width: 100%;
                }

                .sidebar.collapsed .nav-item {
                    justify-content: center;
                    padding: 12px;
                }

                .nav-item:hover {
                    background: var(--surface-light);
                    color: var(--foreground);
                }

                .nav-item.active {
                    background: var(--primary-glow);
                    color: var(--primary);
                }

                .sidebar-footer {
                    padding: 24px 16px;
                    border-top: 1px solid var(--border);
                    display: flex;
                    flex-direction: column;
                    gap: 16px;
                }

                .user-info {
                    display: flex;
                    align-items: center;
                    gap: 12px;
                    padding: 0 8px;
                }

                .sidebar.collapsed .user-info {
                    justify-content: center;
                    padding: 0;
                }

                .user-avatar {
                    width: 36px;
                    height: 36px;
                    background: var(--surface-light);
                    border: 1px solid var(--border);
                    border-radius: 50%;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    font-weight: 600;
                    color: var(--primary);
                }

                .user-details {
                    display: flex;
                    flex-direction: column;
                    overflow: hidden;
                }

                .user-name {
                    font-size: 0.875rem;
                    font-weight: 500;
                    color: var(--foreground);
                    white-space: nowrap;
                    overflow: hidden;
                    text-overflow: ellipsis;
                }

                .logout-btn {
                    color: #f87171;
                }

                .logout-btn:hover {
                    background: rgba(248, 113, 113, 0.1);
                    color: #ef4444;
                }
            `}</style>
        </aside>
    );
}
