'use client';

import {
    getDatasets, uploadFile, saveDataset, SavedDataset,
    getReports, SavedReport, deleteDataset, updateReportName,
    checkDatasetLimit, deleteReport
} from '@/lib/persistence';
import { profileFile, profileFromUrl } from '@/lib/profiler';
import { User } from '@supabase/supabase-js';
import DashboardLayout from './layout/DashboardLayout';
import FileDropzone from '@/components/upload/FileDropzone';
import DataTable from '@/components/ui/DataTable';
import ReportCanvas from './canvas/ReportCanvas';
import { ArrowRight, Activity as SphereIcon, Database, FileText, Plus, Edit2, ExternalLink, Trash2 } from 'lucide-react';

type ViewState = 'home' | 'datasets' | 'upload' | 'reports';

export default function Dashboard() {
    const [activeView, setActiveView] = useState<ViewState>('home');
    const [step, setStep] = useState<'main' | 'profiling' | 'canvas'>('main');
    const [dataset, setDataset] = useState<Record<string, any> | null>(null);
    const [isProfiling, setIsProfiling] = useState(false);
    const [user, setUser] = useState<User | null | undefined>(undefined);
    const [savedDatasets, setSavedDatasets] = useState<SavedDataset[]>([]);
    const [savedReports, setSavedReports] = useState<SavedReport[]>([]);
    const [isLoadingSaved, setIsLoadingSaved] = useState(false);
    const [previewView, setPreviewView] = useState<'stats' | 'preview'>('preview');
    const [initialReportId, setInitialReportId] = useState<string | null>(null);
    const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
    const [showConfirmModal, setShowConfirmModal] = useState(false);
    const [pendingNavigation, setPendingNavigation] = useState<{ view?: ViewState, step?: 'main' | 'profiling' | 'canvas' } | null>(null);
    const canvasRef = React.useRef<{ handleSave: (isSaveAs?: boolean) => Promise<void>; reportName: string } | null>(null);

    const handleViewChange = (view: ViewState) => {
        if (hasUnsavedChanges) {
            setPendingNavigation({ view });
            setShowConfirmModal(true);
            return;
        }
        setActiveView(view);
        setStep('main');
        setInitialReportId(null);
    };

    const confirmNavigation = (action: 'save' | 'saveAs' | 'discard' | 'cancel') => {
        if (action === 'cancel') {
            setShowConfirmModal(false);
            setPendingNavigation(null);
            return;
        }

        if (action === 'discard') {
            setHasUnsavedChanges(false);
            executePendingNavigation();
            return;
        }

        if (action === 'save' || action === 'saveAs') {
            if (canvasRef.current) {
                canvasRef.current.handleSave(action === 'saveAs').then(() => {
                    setHasUnsavedChanges(false);
                    executePendingNavigation();
                });
            }
            return;
        }
    };

    const executePendingNavigation = () => {
        if (pendingNavigation) {
            if (pendingNavigation.view) setActiveView(pendingNavigation.view);
            if (pendingNavigation.step) setStep(pendingNavigation.step);
            setInitialReportId(null);
        }
        setShowConfirmModal(false);
        setPendingNavigation(null);
    };

    useEffect(() => {
        let isInitialFetch = true;

        const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
            console.log('Auth event:', event, !!session);
            const currentUser = session?.user ?? null;

            // Set user state
            setUser(currentUser);

            if (currentUser) {
                if (isInitialFetch || event === 'SIGNED_IN' || event === 'INITIAL_SESSION') {
                    fetchSavedDatasets();
                    fetchSavedReports();
                    isInitialFetch = false;
                }
            } else if (event === 'INITIAL_SESSION' || event === 'SIGNED_OUT') {
                setSavedDatasets([]);
                // Wait a bit to ensure we didn't just miss a fast redirect
                setTimeout(() => {
                    setUser(prev => prev === undefined ? null : prev);
                }, 600);
            }
        });

        return () => subscription.unsubscribe();
    }, []);

    const fetchSavedDatasets = async () => {
        setIsLoadingSaved(true);
        const data = await getDatasets();
        setSavedDatasets(data);
        setIsLoadingSaved(false);
    };

    const fetchSavedReports = async () => {
        const data = await getReports();
        setSavedReports(data);
    };

    const handleLogout = async () => {
        await supabase.auth.signOut();
    };

    const handleFileSelect = async (file: File) => {
        if (!user) return;

        const canUpload = await checkDatasetLimit(user.id);
        if (!canUpload) {
            alert('Límite de datasets alcanzado (3).');
            return;
        }

        setIsProfiling(true);
        setStep('profiling');
        try {
            const profile = await profileFile(file);
            const datasetData = { name: file.name, ...profile };
            setDataset(datasetData);

            if (user) {
                const url = await uploadFile(file, user.id);
                if (url) {
                    const savedDs = await saveDataset({
                        user_id: user.id,
                        name: file.name,
                        file_url: url,
                        columns: profile.columns,
                        stats: profile.stats
                    });
                    setDataset({ id: savedDs.id, name: file.name, ...profile });
                    fetchSavedDatasets();
                }
            }
        } catch (err) {
            console.error('Error profiling file:', err);
            alert('Failed to process file.');
            setStep('main');
        } finally {
            setIsProfiling(false);
        }
    };

    const handleLoadSavedDataset = async (saved: SavedDataset) => {
        setIsProfiling(true);
        setStep('profiling');
        try {
            const profile = await profileFromUrl(saved.file_url, saved.name);
            setDataset({ id: saved.id, name: saved.name, ...profile });
        } catch (err) {
            console.error('Error loading saved dataset:', err);
            alert('Failed to load saved dataset.');
            setStep('main');
        } finally {
            setIsProfiling(false);
        }
    };

    const handleLoadSavedReport = async (report: SavedReport) => {
        setIsProfiling(true);
        setStep('profiling');
        try {
            // 1. Find the dataset metadata
            let ds = savedDatasets.find(d => d.id === report.dataset_id);
            if (!ds) {
                const datasets = await getDatasets();
                ds = datasets.find(d => d.id === report.dataset_id);
            }
            if (!ds) throw new Error('Dataset no encontrado');

            const profile = await profileFromUrl(ds.file_url, ds.name);
            setDataset({ id: ds.id, name: ds.name, ...profile });

            // 2. Switch to canvas
            setInitialReportId(report.id);
            setStep('canvas');
        } catch (err) {
            console.error('Error loading report:', err);
            alert('Fallo al cargar el reporte.');
            setStep('main');
        } finally {
            setIsProfiling(false);
        }
    };

    const handleDeleteDataset = async (ds: SavedDataset) => {
        console.log('handleDeleteDataset triggered for:', ds.id);
        const reportsUsingDs = savedReports.filter(r => r.dataset_id === ds.id);
        if (reportsUsingDs.length > 0) {
            const names = reportsUsingDs.map(r => `"${r.name}"`).join(', ');
            alert(`No se puede eliminar este dataset porque está siendo usado por: ${names}.`);
            return;
        }

        if (window.confirm('¿Estás seguro de que deseas eliminar este dataset?')) {
            try {
                console.log('Confirmation received, deleting...');
                await deleteDataset(ds.id, ds.file_url);
                console.log('Deletion successful, refetching...');
                await fetchSavedDatasets();
            } catch (error) {
                console.error('Error in handleDeleteDataset:', error);
                alert('Error al eliminar el dataset.');
            }
        } else {
            console.log('Deletion cancelled by user.');
        }
    };

    const handleDeleteReport = async (reportId: string) => {
        if (confirm('¿Estás seguro de que deseas eliminar este reporte?')) {
            try {
                await deleteReport(reportId);
                fetchSavedReports();
            } catch (error) {
                alert('Error al eliminar el reporte.');
            }
        }
    };

    const handleRenameReport = async (report: SavedReport) => {
        const newName = prompt('Nuevo nombre para el reporte:', report.name);
        if (newName && newName.trim() !== '' && newName !== report.name) {
            try {
                await updateReportName(report.id, newName.trim());
                fetchSavedReports();
            } catch (error) {
                alert('Error al eliminar el reporte.');
            }
        }
    };

    if (user === undefined) {
        return (
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100vh', background: 'var(--background)' }}>
                <div className="animate-pulse" style={{ color: 'var(--primary)', textAlign: 'center' }}>
                    <div className="logo-orb" style={{ width: '40px', height: '40px', margin: '0 auto 16px' }}></div>
                    <p>Preparando tu espacio...</p>
                </div>
                <style jsx>{`
                    .logo-orb {
                        background: linear-gradient(135deg, var(--primary), var(--secondary));
                        border-radius: 50%;
                        box-shadow: 0 0 20px var(--primary-glow);
                    }
                `}</style>
            </div>
        );
    }

    if (!user) {
        return <LoginView />;
    }

    const renderContent = () => {
        if (step === 'canvas' && dataset) {
            return (
                <ReportCanvas
                    ref={canvasRef}
                    dataset={dataset}
                    initialReportId={initialReportId}
                    onChangesStatusChange={(val) => setHasUnsavedChanges(val)}
                />
            );
        }

        if (step === 'profiling' && dataset) {
            return (
                <div style={{ padding: '40px' }} className="animate-in fade-in duration-500">
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '32px' }}>
                        <div>
                            <h2 style={{ fontSize: '1.5rem', fontWeight: 600, color: '#fff' }}>{dataset.name}</h2>
                            <div style={{ display: 'flex', gap: '8px', marginTop: '12px' }}>
                                <button
                                    onClick={() => setPreviewView('preview')}
                                    className={`tab-btn ${previewView === 'preview' ? 'active' : ''}`}
                                >
                                    Previsualización
                                </button>
                                <button
                                    onClick={() => setPreviewView('stats')}
                                    className={`tab-btn ${previewView === 'stats' ? 'active' : ''}`}
                                >
                                    Estadísticas
                                </button>
                            </div>
                        </div>
                        <div style={{ display: 'flex', gap: '16px' }}>
                            <button
                                className="btn-secondary"
                                onClick={() => setStep('main')}
                                style={{
                                    padding: '12px 24px',
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '8px',
                                    background: 'rgba(255,255,255,0.05)',
                                    border: '1px solid var(--border)',
                                    color: 'var(--text-muted)'
                                }}
                            >
                                Cancelar
                            </button>
                            <button
                                className="btn-primary"
                                onClick={() => setStep('canvas')}
                                style={{
                                    padding: '12px 28px',
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '10px',
                                    fontSize: '1rem',
                                    fontWeight: 600,
                                    boxShadow: '0 4px 15px var(--primary-glow)'
                                }}
                            >
                                Crear Reporte <ArrowRight size={20} />
                            </button>
                        </div>
                    </div>

                    {previewView === 'stats' ? (
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
                            {dataset.stats.map((col) => (
                                <div key={col.column} className="glass-card" style={{ padding: '24px' }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
                                        <span style={{ fontWeight: 600 }}>{col.column}</span>
                                        <span className="badge">{col.type}</span>
                                    </div>
                                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                                        <div>
                                            <p className="stat-label">Únicos</p>
                                            <p className="stat-value">{col.unique}</p>
                                        </div>
                                        <div>
                                            <p className="stat-label">Nulos</p>
                                            <p className="stat-value">{col.nulls}</p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="glass-card" style={{ overflow: 'hidden' }}>
                            <DataTable columns={dataset.columns} data={dataset.preview} />
                        </div>
                    )}

                    <style jsx>{`
                        .tab-btn {
                            background: var(--surface);
                            padding: 6px 16px;
                            border-radius: 20px;
                            color: var(--text-muted);
                            border: none;
                            cursor: pointer;
                        }
                        .tab-btn.active {
                            background: var(--primary);
                            color: white;
                        }
                        .badge {
                            font-size: 0.7rem;
                            color: var(--primary);
                            background: var(--primary-glow);
                            padding: 4px 8px;
                            border-radius: 6px;
                        }
                        .stat-label { font-size: 0.75rem; color: var(--text-muted); }
                        .stat-value { font-weight: 600; font-size: 1.125rem; }
                    `}</style>
                </div>
            );
        }

        switch (activeView) {
            case 'home':
                return (
                    <div style={{ padding: '40px' }}>
                        <header style={{ marginBottom: '48px' }}>
                            <h1 style={{ fontSize: '2.5rem', fontWeight: 700, marginBottom: '8px' }}>
                                Hola, <span className="gradient-text">{user.user_metadata.full_name?.split(' ')[0] || 'Usuario'}</span>
                            </h1>
                            <p style={{ color: 'var(--text-muted)', fontSize: '1.125rem' }}>Bienvenido a tu panel de control de Sphere.</p>
                        </header>

                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '32px', marginBottom: '48px' }}>
                            <div className="glass-card action-card" onClick={() => setActiveView('upload')}>
                                <div className="card-icon"><Plus size={32} /></div>
                                <div>
                                    <h3>Nuevo Dataset</h3>
                                    <p>Sube un archivo para empezar el análisis.</p>
                                </div>
                            </div>
                            <div className="glass-card action-card" onClick={() => setActiveView('datasets')}>
                                <div className="card-icon"><Database size={32} /></div>
                                <div>
                                    <h3>Explorar Datos</h3>
                                    <p>Mira tus datasets cargados previamente.</p>
                                </div>
                            </div>
                        </div>

                        {savedReports.length > 0 && (
                            <section>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '24px' }}>
                                    <SphereIcon size={20} color="var(--accent)" />
                                    <h2 style={{ fontSize: '1.25rem', fontWeight: 600 }}>Reportes Recientes</h2>
                                </div>
                                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px' }}>
                                    {savedReports.slice(0, 3).map(report => (
                                        <div key={report.id} className="glass-card ds-card" onClick={() => handleLoadSavedReport(report)}>
                                            <div className="ds-icon" style={{ color: 'var(--accent)' }}><SphereIcon size={20} /></div>
                                            <div className="ds-info">
                                                <h4>{report.name}</h4>
                                                <p>{new Date(report.created_at).toLocaleDateString()}</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </section>
                        )}

                        <style jsx>{`
                            .action-card {
                                padding: 32px;
                                display: flex;
                                align-items: center;
                                gap: 24px;
                                cursor: pointer;
                                transition: all 0.2s;
                            }
                            .action-card:hover { transform: translateY(-4px); border-color: var(--primary); }
                            .card-icon { color: var(--primary); }
                            .ds-card {
                                padding: 16px;
                                display: flex;
                                align-items: center;
                                gap: 16px;
                                cursor: pointer;
                            }
                            .ds-icon { background: var(--surface); padding: 10px; border-radius: 8px; color: var(--primary); }
                            .ds-info h4 { font-size: 0.9375rem; margin: 0; }
                            .ds-info p { font-size: 0.8125rem; color: var(--text-muted); margin: 0; }
                        `}</style>
                    </div>
                );
            case 'datasets':
                return (
                    <div style={{ padding: '40px' }}>
                        <header style={{ marginBottom: '32px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
                            <div>
                                <h2 style={{ fontSize: '1.75rem', fontWeight: 600 }}>Mis Datasets</h2>
                                <p style={{ color: 'var(--text-muted)' }}>Gestiona todos los datos que has subido a la plataforma.</p>
                            </div>
                            <div style={{ fontSize: '0.875rem', color: savedDatasets.length >= 3 ? '#fbbf24' : 'var(--text-muted)', background: 'var(--surface)', padding: '4px 12px', borderRadius: '20px', border: '1px solid var(--border)' }}>
                                {savedDatasets.length}/3 Datasets
                            </div>
                        </header>

                        {isLoadingSaved ? (
                            <p>Cargando...</p>
                        ) : savedDatasets.length > 0 ? (
                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '24px' }}>
                                {savedDatasets.map(ds => (
                                    <div key={ds.id} className="glass-card ds-item" onClick={() => handleLoadSavedDataset(ds)}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '16px' }}>
                                            <FileText size={24} color="var(--primary)" />
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                                                    {new Date(ds.created_at).toLocaleDateString()}
                                                </span>
                                                <ThreeDotMenu items={[
                                                    { label: 'Abrir', icon: <ExternalLink size={16} />, onClick: () => handleLoadSavedDataset(ds) },
                                                    { label: 'Eliminar', icon: <Trash2 size={16} />, onClick: () => handleDeleteDataset(ds), variant: 'danger' }
                                                ]} />
                                            </div>
                                        </div>
                                        <h3 style={{ fontSize: '1rem', marginBottom: '8px' }}>{ds.name}</h3>
                                        <p style={{ fontSize: '0.8125rem', color: 'var(--text-muted)' }}>
                                            {ds.columns?.length || 0} Columnas • {ds.stats?.length || 0} Métricas detectadas
                                        </p>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="glass-card" style={{ padding: '60px', textAlign: 'center' }}>
                                <Database size={48} color="var(--text-muted)" style={{ marginBottom: '16px' }} />
                                <h3>No hay datasets aún</h3>
                                <button className="btn-primary" style={{ marginTop: '20px' }} onClick={() => setActiveView('upload')}>Subir mi primer dataset</button>
                            </div>
                        )}
                        <style jsx>{`
                            .ds-item { padding: 24px; cursor: pointer; transition: all 0.2s; }
                            .ds-item:hover { border-color: var(--primary); transform: translateY(-2px); }
                        `}</style>
                    </div>
                );
            case 'upload':
                return (
                    <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto' }}>
                        <header style={{ marginBottom: '32px', textAlign: 'center' }}>
                            <h2 style={{ fontSize: '1.75rem', fontWeight: 600 }}>Subir Dataset</h2>
                            <p style={{ color: 'var(--text-muted)' }}>Aceptamos CSV, Excel (xlsx) y JSON.</p>
                        </header>
                        <FileDropzone onFileSelect={handleFileSelect} />
                        {isProfiling && (
                            <div style={{ marginTop: '24px', textAlign: 'center' }}>
                                <p className="animate-pulse">Procesando archivo...</p>
                            </div>
                        )}
                    </div>
                );
            case 'reports':
                return (
                    <div style={{ padding: '40px' }}>
                        <header style={{ marginBottom: '32px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
                            <div>
                                <h2 style={{ fontSize: '1.75rem', fontWeight: 600 }}>Mis Reportes</h2>
                                <p style={{ color: 'var(--text-muted)' }}>Vuelve a tus visualizaciones guardadas.</p>
                            </div>
                            <div style={{ fontSize: '0.875rem', color: savedReports.length >= 10 ? '#fbbf24' : 'var(--text-muted)', background: 'var(--surface)', padding: '4px 12px', borderRadius: '20px', border: '1px solid var(--border)' }}>
                                {savedReports.length} Reportes
                            </div>
                        </header>

                        {savedReports.length > 0 ? (
                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '24px' }}>
                                {savedReports.map(report => (
                                    <div key={report.id} className="glass-card report-item" onClick={() => handleLoadSavedReport(report)}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '16px' }}>
                                            <SphereIcon size={24} color="var(--accent)" />
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                                                    {new Date(report.created_at).toLocaleDateString()}
                                                </span>
                                                <ThreeDotMenu items={[
                                                    { label: 'Abrir', icon: <ExternalLink size={16} />, onClick: () => handleLoadSavedReport(report) },
                                                    { label: 'Cambiar nombre', icon: <Edit2 size={16} />, onClick: () => handleRenameReport(report) },
                                                    { label: 'Eliminar', icon: <Trash2 size={16} />, onClick: () => handleDeleteReport(report.id), variant: 'danger' }
                                                ]} />
                                            </div>
                                        </div>
                                        <h3 style={{ fontSize: '1.125rem', marginBottom: '8px' }}>{report.name}</h3>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginTop: '16px' }}>
                                            <div className="badge-small">{report.widgets.length} Gráficos</div>
                                            <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                                                {savedDatasets.find(d => d.id === report.dataset_id)?.name || 'Dataset asociado'}
                                            </span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="glass-card" style={{ padding: '60px', textAlign: 'center' }}>
                                <SphereIcon size={48} color="var(--text-muted)" style={{ marginBottom: '16px' }} />
                                <h3>No tienes reportes guardados</h3>
                                <p style={{ color: 'var(--text-muted)', marginTop: '8px' }}>Empresa por subir un dataset y crear visualizaciones.</p>
                                <button className="btn-primary" style={{ marginTop: '24px' }} onClick={() => handleViewChange('upload')}>Empezar ahora</button>
                            </div>
                        )}
                        <style jsx>{`
                            .report-item { padding: 24px; cursor: pointer; transition: all 0.2s; position: relative; overflow: hidden; }
                            .report-item:hover { border-color: var(--accent); transform: translateY(-4px); }
                            .report-item::after {
                                content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 2px;
                                background: linear-gradient(to right, transparent, var(--accent), transparent);
                                opacity: 0; transition: opacity 0.2s;
                            }
                            .report-item:hover::after { opacity: 1; }
                            .badge-small {
                                font-size: 0.65rem; background: var(--surface-light); padding: 4px 8px; border-radius: 4px; color: var(--accent);
                            }
                        `}</style>
                    </div>
                );
            default:
                return null;
        }
    };

    return (
        <DashboardLayout
            activeView={activeView}
            onViewChange={handleViewChange}
            onLogout={handleLogout}
            userName={user.user_metadata.full_name || user.email}
        >
            {renderContent()}

            {/* Unsaved Changes Confirmation Modal */}
            {showConfirmModal && (
                <div style={{
                    position: 'fixed',
                    inset: 0,
                    zIndex: 100,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    background: 'rgba(0,0,0,0.8)',
                    backdropFilter: 'blur(8px)'
                }}>
                    <div className="glass-card" style={{ padding: '32px', maxWidth: '450px', width: '90%', border: '1px solid var(--border)' }}>
                        <h3 style={{ fontSize: '1.25rem', marginBottom: '12px' }}>Cambios sin guardar</h3>
                        <p style={{ color: 'var(--text-muted)', marginBottom: '24px', fontSize: '0.9375rem', lineHeight: '1.5' }}>
                            Tienes cambios pendientes en tu reporte. ¿Qué deseas hacer antes de salir?
                        </p>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                            <button
                                className="btn-primary"
                                onClick={() => confirmNavigation('save')}
                                style={{ padding: '12px' }}
                            >
                                Guardar y salir
                            </button>
                            {canvasRef.current?.reportName && (
                                <button
                                    className="btn-secondary"
                                    onClick={() => confirmNavigation('saveAs')}
                                    style={{ padding: '12px', background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border)' }}
                                >
                                    Guardar como...
                                </button>
                            )}
                            <button
                                onClick={() => confirmNavigation('discard')}
                                style={{ padding: '12px', background: 'transparent', border: 'none', color: '#f87171', cursor: 'pointer', fontSize: '0.875rem' }}
                            >
                                Descartar cambios
                            </button>
                            <button
                                onClick={() => confirmNavigation('cancel')}
                                style={{ padding: '12px', background: 'transparent', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: '0.875rem' }}
                            >
                                Cancelar
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </DashboardLayout>
    );
}
